// run.js
var fs = require("fs");
var path = require("path");
var SKILL_VERSION = true ? "260219.123126" : "1.2.0-dev";
var alasql;
try {
  alasql = require_alasql_fs().promise;
} catch (e) {
  console.error("\u9519\u8BEF: \u65E0\u6CD5\u52A0\u8F7D alasql \u6A21\u5757");
  console.error("");
  console.error("\u8BF7\u5148\u5728 skills \u76EE\u5F55\u4E0B\u6267\u884C: pnpm install");
  console.error("");
  console.error("Windows \u7528\u6237\u4E5F\u53EF\u4EE5\u4F7F\u7528: run.bat <\u6587\u4EF6\u8DEF\u5F84>");
  process.exit(1);
}
var excelFile = process.argv[2];
var operation = process.argv[3];
function showHelp() {
  console.log(`
Excel \u901A\u7528\u67E5\u8BE2\u5DE5\u5177 v${SKILL_VERSION}

\u7528\u6CD5:
  node skill.js <\u6587\u4EF6\u8DEF\u5F84> [\u64CD\u4F5C]

\u53C2\u6570:
  \u6587\u4EF6\u8DEF\u5F84   Excel \u6587\u4EF6\u8DEF\u5F84\uFF08\u5FC5\u9700\uFF09
  \u64CD\u4F5C       \u53EF\u9009\u64CD\u4F5C\uFF08\u89C1\u4E0B\u65B9\uFF09

\u64CD\u4F5C\u7C7B\u578B:
  (\u65E0\u53C2\u6570)   \u663E\u793A\u6570\u636E\u6982\u89C8
  "\u5173\u952E\u8BCD"   \u5168\u6587\u641C\u7D22\uFF08\u5728\u6240\u6709\u5217\u4E2D\u67E5\u627E\u5305\u542B\u5173\u952E\u8BCD\u7684\u8BB0\u5F55\uFF09
  "*"        \u5BFC\u51FA\u5168\u90E8\u6570\u636E\u4E3A JSON

\u793A\u4F8B:
  # \u6570\u636E\u6982\u89C8
  node skill.js data.xlsx

  # \u5173\u952E\u8BCD\u641C\u7D22
  node skill.js data.xlsx "\u5173\u952E\u8BCD"

  # \u5BFC\u51FA JSON
  node skill.js data.xlsx "*" > output.json

\u5FEB\u6377\u9009\u9879:
  -h, --help     \u663E\u793A\u6B64\u5E2E\u52A9\u4FE1\u606F
  -v, --version  \u663E\u793A\u7248\u672C\u4FE1\u606F

\u63D0\u793A:
  - \u652F\u6301\u4E2D\u6587\u6587\u4EF6\u540D\u548C\u5217\u540D
  - \u65E0\u9700\u5B89\u88C5\u4F9D\u8D56
`);
}
function showVersion() {
  console.log(`Excel \u901A\u7528\u67E5\u8BE2\u5DE5\u5177 v${SKILL_VERSION}`);
  console.log("\u57FA\u4E8E AlaSQL + SheetJS");
  console.log("\u8DE8\u5E73\u53F0\u652F\u6301: Windows, macOS, Linux");
}
if (!excelFile || excelFile === "-h" || excelFile === "--help") {
  showHelp();
  process.exit(0);
}
if (excelFile === "-v" || excelFile === "--version") {
  showVersion();
  process.exit(0);
}
if (!fs.existsSync(excelFile)) {
  console.error(`\u9519\u8BEF: \u6587\u4EF6\u4E0D\u5B58\u5728 - ${excelFile}`);
  process.exit(1);
}
console.log("\n" + "=".repeat(70));
console.log("\u{1F4CA} Excel \u6570\u636E\u67E5\u8BE2");
console.log("=".repeat(70));
console.log(`
\u6587\u4EF6: ${excelFile}
`);
(async () => {
  try {
    const data = await alasql(
      `SELECT * FROM XLSX("${excelFile}", {autoExt: false})`
    );
    if (!data || data.length === 0) {
      console.log("\u26A0\uFE0F  \u6587\u4EF6\u4E3A\u7A7A\u6216\u65E0\u6CD5\u8BFB\u53D6");
      return;
    }
    if (operation === "*") {
      console.log(JSON.stringify(data, null, 2));
      return;
    }
    if (operation) {
      console.log(`\u{1F50D} \u7B5B\u9009\u7ED3\u679C: "${operation}"`);
      console.log("=".repeat(70));
      console.log(`\u6587\u4EF6: ${excelFile}
`);
      const filtered = data.filter(
        (row) => Object.values(row).some((val) => String(val).includes(operation))
      );
      if (filtered.length > 0) {
        console.log(`\u2713 \u627E\u5230 ${filtered.length} \u6761\u5339\u914D\u8BB0\u5F55
`);
        if (filtered.length <= 50) {
          console.table(filtered);
        } else {
          console.log(`
\u524D 20 \u6761:
`);
          console.table(filtered.slice(0, 20));
          console.log(`
... \u8FD8\u6709 ${filtered.length - 20} \u6761\u8BB0\u5F55
`);
        }
      } else {
        console.log("\u26A0\uFE0F  \u672A\u627E\u5230\u5339\u914D\u8BB0\u5F55");
      }
      return;
    }
    console.log(`\u{1F4C8} \u603B\u8BB0\u5F55\u6570: ${data.length}`);
    console.log(`\u{1F4CB} \u5217\u6570: ${Object.keys(data[0]).length}`);
    console.log(`\u{1F4CB} \u5217\u540D: ${Object.keys(data[0]).join(", ")}
`);
    console.log("\u{1F50D} \u6570\u636E\u9884\u89C8\uFF08\u524D 3 \u6761\uFF09:\n");
    data.slice(0, 3).forEach((row, i) => {
      console.log(`[${i + 1}]`);
      Object.entries(row).forEach(([key, val]) => {
        const strVal = String(val || "");
        const display = strVal.length > 40 ? strVal.substring(0, 40) + "..." : strVal;
        console.log(`  ${key}: ${display}`);
      });
      console.log("");
    });
    console.log("\u{1F4CA} \u5217\u4FE1\u606F\u5206\u6790:\n");
    Object.keys(data[0]).forEach((col, idx) => {
      const nonNull = data.filter(
        (row) => row[col] !== null && row[col] !== void 0 && row[col] !== ""
      );
      const uniqueValues = [...new Set(nonNull.map((row) => String(row[col])))];
      console.log(`${idx + 1}. ${col}`);
      console.log(`   \u975E\u7A7A: ${nonNull.length}/${data.length} (${(nonNull.length / data.length * 100).toFixed(1)}%)`);
      console.log(`   \u552F\u4E00\u503C: ${uniqueValues.length} \u4E2A`);
      if (uniqueValues.length <= 8) {
        console.log(`   \u503C: ${uniqueValues.join(", ")}`);
      }
    });
    console.log("\n" + "\u2500".repeat(70));
    console.log("\n\u{1F4A1} \u4F7F\u7528\u793A\u4F8B:\n");
    console.log(`  npx --yes --package=alasql --package=xlsx node run.js ${excelFile} "\u5173\u952E\u8BCD"`);
    console.log(`  npx --yes --package=alasql --package=xlsx node run.js ${excelFile} "*" > output.json`);
  } catch (error) {
    console.error(`
\u274C \u9519\u8BEF: ${error.message}`);
    if (error.message.includes("find XLSX") || error.message.includes("format")) {
      console.error("\n\u{1F4A1} \u63D0\u793A: \u8BF7\u786E\u4FDD\u6587\u4EF6\u683C\u5F0F\u6B63\u786E\uFF08.xlsx \u6216 .xls\uFF09");
    }
    process.exit(1);
  }
  console.log("\n" + "=".repeat(70));
  console.log("\u2705 \u5B8C\u6210\uFF01");
  console.log("=".repeat(70) + "\n");
})();
